import{_ as e,o as l,c as t,at as o}from"./chunks/framework.CY22Hent.js";const d=JSON.parse('{"title":"系统分析师笔记22_系统分析师论文写作要点","description":"","frontmatter":{"title":"系统分析师笔记22_系统分析师论文写作要点","date":"2026-08-29T00:00:00.000Z","lastUpdated":"2026-08-29T00:00:00.000Z","categories":["软考"],"tags":["软考"]},"headers":[],"relativePath":"blogs/软考/系统分析师笔记22_系统分析师论文写作要点.md","filePath":"blogs/软考/系统分析师笔记22_系统分析师论文写作要点.md"}'),i={name:"blogs/软考/系统分析师笔记22_系统分析师论文写作要点.md"};function r(h,a,p,c,_,n){return l(),t("div",null,[...a[0]||(a[0]=[o('<p>[toc]</p><h1 id="系统分析师笔记22-系统分析师论文写作要点" tabindex="-1">系统分析师笔记22_系统分析师论文写作要点 <a class="header-anchor" href="#系统分析师笔记22-系统分析师论文写作要点" aria-label="Permalink to &quot;系统分析师笔记22_系统分析师论文写作要点&quot;">​</a></h1><p>该笔记内容来自《系统分析师教程》第2版。</p><h2 id="写作注意事项" tabindex="-1">写作注意事项 <a class="header-anchor" href="#写作注意事项" aria-label="Permalink to &quot;写作注意事项&quot;">​</a></h2><p>系统分析师的论文题目对于考生具有较大难度，一方面，考生需要掌握论文题目中系统分析设计的专业知识：另一方面，论文的撰写需要结合考生自身的项目经历。</p><p>因此，如何将自己的项目经历和专业知识进行有机结合，将专业知识的理论和专业知识的工程相结合，撰写出一篇高质量的系统分析师论文，对考生来说具有比较大的挑战。</p><h2 id="如何解答试题" tabindex="-1">如何解答试题 <a class="header-anchor" href="#如何解答试题" aria-label="Permalink to &quot;如何解答试题&quot;">​</a></h2><p>如果做好了充分的论文准备，平时按照既有格式进行了练习，则临场就可以从容自如。如果试题与准备的内容出入很大，那也不要紧张，选定自己把握最大的论题，按平时的速度写下去。</p><h3 id="论文解答步骤" tabindex="-1">论文解答步骤 <a class="header-anchor" href="#论文解答步骤" aria-label="Permalink to &quot;论文解答步骤&quot;">​</a></h3><p>根据论文答题的一般步骤，本节给出一个通用的框架，考生可根据考试现场题目的情况和自己的实际进行解答，不必拘泥于本框架的约束。</p><blockquote><p>时间分配</p></blockquote><p>下面给出论文答题各步骤的时间分配。</p><ul><li>试题选择 3分钟</li><li>论文构思 12分钟</li><li>写摘要 15分钟</li><li>正文撰写 80分钟</li><li>检查修改 10分钟</li></ul><blockquote><p>试题选择</p></blockquote><p>在试题选择时要注意：</p><ul><li>( 1) 选择自己最熟悉的，最有把握的题目。</li><li>( 2) 不要忘记选择题号和填写考号。</li></ul><blockquote><p>论文构思</p></blockquote><p>在论文构思时要注意:</p><ul><li>( 1) 构思论点(主张)和下过功夫的地方。</li><li>( 2) 将构思的项目内容与论点相结合。</li><li>( 3)决定写入摘要的内容。</li><li>( 4)划分章节，把内容写成简单草稿(几字带过，无须丰富细节)。</li><li>( 5)大体字数分配。</li></ul><blockquote><p>写摘要</p></blockquote><p>写摘要时要注意: 用语简洁、明快，阐述自己的论点。</p><blockquote><p>正文撰写</p></blockquote><p>正文撰写时要注意:</p><ul><li>( 1) 按草稿进行构思、追忆项目素材(包括收集的素材)进行编写。</li><li>( 2) 控制好内容篇幅。</li><li>( 3) 与构思有出入的地方，注意不要前后矛盾。</li></ul><blockquote><p>检查修改</p></blockquote><p>检查修改主要是检查有无遗漏、有无错别字等。</p><h2 id="论文写作方法" tabindex="-1">论文写作方法 <a class="header-anchor" href="#论文写作方法" aria-label="Permalink to &quot;论文写作方法&quot;">​</a></h2><p>两个小时内写出一篇近3000字的文章不是一件容易的事情。根据以往的经验，考生在写作过程中必须逻辑清晰，并且要保持一定的撰写速度，才可以在有限的时间内较好地完成论文写作。</p><p>下面针对如何撰写好摘要和论文的正文部分分别进行说明。</p><h3 id="如何写好摘要" tabindex="-1">如何写好摘要 <a class="header-anchor" href="#如何写好摘要" aria-label="Permalink to &quot;如何写好摘要&quot;">​</a></h3><h3 id="如何写好正文" tabindex="-1">如何写好正文 <a class="header-anchor" href="#如何写好正文" aria-label="Permalink to &quot;如何写好正文&quot;">​</a></h3><h3 id="摘要和正文的关系" tabindex="-1">摘要和正文的关系 <a class="header-anchor" href="#摘要和正文的关系" aria-label="Permalink to &quot;摘要和正文的关系&quot;">​</a></h3><h2 id="常见问题及解决办法" tabindex="-1">常见问题及解决办法 <a class="header-anchor" href="#常见问题及解决办法" aria-label="Permalink to &quot;常见问题及解决办法&quot;">​</a></h2><h2 id="论文评分标准" tabindex="-1">论文评分标准 <a class="header-anchor" href="#论文评分标准" aria-label="Permalink to &quot;论文评分标准&quot;">​</a></h2>',34)])])}const s=e(i,[["render",r]]);export{d as __pageData,s as default};
